const input = $json.body ?? $json;
const text = String(input.text ?? '');
const action = String(input.action ?? 'read_only');
const requestedDestination = String(input.destination ?? 'local');
const sensitivePatterns = [
  /passport|bank|account number|medical|password|secret|private key|seed phrase/i,
  /child|children|home address|identity document/i
];
const containsSensitiveData = sensitivePatterns.some((r) => r.test(text));
const route = containsSensitiveData ? 'local' : (requestedDestination === 'cloud' ? 'cloud' : 'local');
const mutatingActions = new Set(['send_email','create_event','update_notion','delete','purchase','share_external']);
const requiresApproval = mutatingActions.has(action);
return [{
  json: {
    requestId: input.requestId ?? ('demo-' + Date.now()),
    text,
    action,
    route,
    containsSensitiveData,
    requiresApproval,
    approved: Boolean(input.approved),
    policyVersion: 'demo-1',
    note: 'Portfolio demo only. No external action is executed by this workflow.'
  }
}];

const x = $json;
const approvalState = x.requiresApproval ? (x.approved ? 'approved' : 'blocked_pending_human_approval') : 'not_required';
const nextStep =
  approvalState === 'blocked_pending_human_approval'
    ? 'Present proposed action to household owner; do not mutate external systems.'
    : x.route === 'local'
      ? 'Route content to client-owned local model (for example Ollama/LM Studio) and keep raw sensitive text off cloud services.'
      : 'Cloud processing may be used only for the minimum non-sensitive payload allowed by client policy.';
return [{
  json: {
    ...x,
    approvalState,
    nextStep,
    actionExecution: 'NOT_IMPLEMENTED_IN_DEMO',
    audit: {
      timestamp: new Date().toISOString(),
      route: x.route,
      requiresApproval: x.requiresApproval,
      approvalState
    }
  }
}];
